"""Build upright SDK masks and the legacy theme's rotated masks from local SVGs."""
from pathlib import Path
import io, json
import resvg_py
from PIL import Image, ImageOps

root = Path(__file__).resolve().parents[2]
source = root / 'assets_local/navigation-icons'
lines = ['#pragma once', '#include <Icon.h>', '',
         '// Generated by tools_local/navigation_art/generate.py from the local reference SVGs.',
         '// clang-format off', 'namespace navicons {']
atlas = []

def raster(path, size, extent):
    # Resample only during generation. Runtime controls draw prepacked one-bit masks.
    data = resvg_py.svg_to_bytes(svg_path=str(path), width=512, height=512, background='white')
    image = Image.open(io.BytesIO(data)).convert('L')
    box = image.point(lambda v: 255 if v < 180 else 0).getbbox()
    if not box:
        raise ValueError('Empty icon: '+path.name)
    image = image.crop(box)
    image.thumbnail((extent, extent), Image.Resampling.LANCZOS)
    canvas = Image.new('L', (size, size), 255)
    canvas.paste(image, ((size-image.width)//2, (size-image.height)//2))
    return canvas.point(lambda v: 255 if v >= 160 else 0)

def emit(name, image):
    size = image.width
    bits=[];ys=[]
    for y in range(size):
        for x in range(0, size, 8):
            value=0
            for bit in range(8):
                white = x+bit >= size or image.getpixel((x+bit,y)) != 0
                value |= int(white) << (7-bit)
                if not white: ys.append(y)
            bits.append(value)
    center = round(sum(ys)/len(ys))
    lines.append(f'inline constexpr uint8_t {name}Bits[] = {{')
    lines.extend('  '+','.join(f'0x{n:02x}' for n in bits[i:i+24])+',' for i in range(0,len(bits),24))
    lines.extend(['};',f'inline constexpr freeink::Icon {name}{{{size}, {size}, {center}, {name}Bits}};'])

for path in sorted(source.glob('*.svg')):
    for size in (24,32,64):
        image=raster(path,size,size-4 if size < 64 else 60)
        emit(path.stem+str(size), image)
        if size==32:atlas.append((path.stem,image))
    emit(path.stem+'Row64',raster(path,64,44))

# GfxRenderer::drawIcon reverses this rotation; FreeInkUI consumes upright masks.
legacy={'folder':'Folder','recent':'Stats','library':'Library','transfer':'Send',
        'settings2':'Gear','wifi':'Wifi','hotspot':'Hotspot'}
for filename,name in legacy.items():
    image=raster(source/(name+'.svg'),32,28).transpose(Image.Transpose.ROTATE_90)
    symbol=name+'Legacy32';emit(symbol,image)
    variable={'folder':'FolderIcon','recent':'RecentIcon','library':'LibraryIcon','transfer':'TransferIcon',
              'settings2':'Settings2Icon','wifi':'WifiIcon','hotspot':'HotspotIcon'}[filename]
    (root/f'src/components/icons/{filename}.h').write_text(
        '#pragma once\n#include "../../apps_local/ui/NavigationIcons.h"\n'
        '// Generated by tools_local/navigation_art/generate.py.\n'
        f'inline constexpr auto& {variable} = navicons::{symbol}Bits;\n','utf8')
for name in ('Games','Apps'):emit(name+'Legacy32',raster(source/(name+'.svg'),32,28).transpose(Image.Transpose.ROTATE_90))
(root/'src/components/icons/shelfIcons.h').write_text(
    '#pragma once\n#include "../../apps_local/ui/NavigationIcons.h"\n'
    '// Generated by tools_local/navigation_art/generate.py.\n'
    'inline constexpr auto& ShelfGamesIcon = navicons::GamesLegacy32Bits;\n'
    'inline constexpr auto& ShelfAppsIcon = navicons::AppsLegacy32Bits;\n','utf8')
lines.extend(['}  // namespace navicons','// clang-format on'])
(root/'src/apps_local/ui/NavigationIcons.h').write_text('\n'.join(lines)+'\n','utf8')
print('Generated',len(atlas),'icons at 24/32/64 px and normalized settings rows')
